const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'cover', index: 1, title: 'GitHub Trending Repos Snapshot' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Right side decorative block
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.2, y: 0, w: 3.8, h: 5.625,
    fill: { color: theme.secondary }
  });

  // Accent diagonal stripe
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.9, y: 0, w: 0.5, h: 5.625,
    fill: { color: theme.accent }
  });

  // Small decorative shapes on right
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7, y: 0.8, w: 2.2, h: 0.06,
    fill: { color: theme.accent }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7, y: 4.8, w: 2.2, h: 0.06,
    fill: { color: theme.accent }
  });

  // Big number callout
  slide.addText("20", {
    x: 6.8, y: 1.2, w: 2.6, h: 2.5,
    fontSize: 120, fontFace: "Trebuchet MS",
    color: theme.accent, bold: true, align: "center", valign: "middle",
    transparency: 20
  });
  slide.addText("TRENDING REPOS", {
    x: 6.8, y: 3.4, w: 2.6, h: 0.5,
    fontSize: 14, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "top",
    charSpacing: 4
  });

  // Main title
  slide.addText("GitHub Trending\nRepos Snapshot", {
    x: 0.6, y: 1.0, w: 5.0, h: 2.0,
    fontSize: 52, fontFace: "Trebuchet MS",
    color: "FFFFFF", bold: true, align: "left", valign: "middle",
    lineSpacingMultiple: 0.9
  });

  // Subtitle
  slide.addText("The Rise of AI Coding Agents\n& Claude Code Skills", {
    x: 0.6, y: 2.9, w: 5.0, h: 1.0,
    fontSize: 22, fontFace: "Calibri",
    color: theme.accent, bold: false, align: "left", valign: "top"
  });

  // Divider line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 4.1, w: 3.0, h: 0.04,
    fill: { color: theme.accent }
  });

  // Footer info
  slide.addText("Powered by OSSInsight  |  10.6B+ GitHub Events  |  May 2026", {
    x: 0.6, y: 4.4, w: 5.0, h: 0.4,
    fontSize: 13, fontFace: "Calibri",
    color: "90e0ef", bold: false, align: "left", valign: "top"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "f0f9ff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

