const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 2, title: 'OSSInsight Tracks 10.6 Billion GitHub Events in Real Time' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("OSSInsight Tracks 10.6 Billion\nGitHub Events in Real Time", {
    x: 0.5, y: 0.3, w: 9, h: 1.0,
    fontSize: 32, fontFace: "Trebuchet MS",
    color: theme.primary, bold: true, align: "left", valign: "middle"
  });

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.35, w: 2.5, h: 0.05,
    fill: { color: theme.accent }
  });

  // Description
  slide.addText("A free, real-time analytics platform providing deep insights into open-source repositories, developers, and organizations.", {
    x: 0.5, y: 1.55, w: 9, h: 0.5,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", valign: "top"
  });

  // Stat cards row
  const stats = [
    { value: "10.6B+", label: "GitHub Events\nTracked" },
    { value: "Stars", label: "Repository\nStargazers" },
    { value: "PRs", label: "Pull Requests\n& Reviews" },
    { value: "Issues", label: "Issue Tracking\n& Commits" }
  ];

  const cardW = 2.05;
  const cardH = 2.2;
  const startX = 0.5;
  const gap = 0.15;
  const cardY = 2.3;

  stats.forEach((stat, i) => {
    const cx = startX + i * (cardW + gap);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: cardH,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.08 },
      rectRadius: 0.08
    });

    // Top accent stripe on card
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx + 0.2, y: cardY + 0.2, w: cardW - 0.4, h: 0.04,
      fill: { color: theme.accent }
    });

    // Value
    slide.addText(stat.value, {
      x: cx, y: cardY + 0.4, w: cardW, h: 0.9,
      fontSize: i === 0 ? 40 : 28, fontFace: "Trebuchet MS",
      color: theme.primary, bold: true, align: "center", valign: "middle"
    });

    // Label
    slide.addText(stat.label, {
      x: cx, y: cardY + 1.3, w: cardW, h: 0.7,
      fontSize: 13, fontFace: "Calibri",
      color: theme.secondary, bold: false, align: "center", valign: "top"
    });
  });

  // Scoring methodology note
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.75, w: 9, h: 0.55,
    fill: { color: theme.primary }
  });
  slide.addText("Trending Score = Stars Score + Forks Score + Base Score  —  Data reflects the past 24 hours across all programming languages", {
    x: 0.7, y: 4.75, w: 8.6, h: 0.55,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "middle"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "f0f9ff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

