const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 4, title: 'Language Distribution' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Python and TypeScript Dominate\nTrending Repos' Language Mix", {
    x: 0.5, y: 0.25, w: 9, h: 0.9,
    fontSize: 28, fontFace: "Trebuchet MS",
    color: theme.primary, bold: true, align: "left", valign: "middle"
  });

  // Accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.2, w: 2.0, h: 0.04,
    fill: { color: theme.accent }
  });

  // Donut chart
  const chartData = [
    {
      name: "Languages",
      labels: ["Python", "TypeScript", "HTML", "Rust", "Swift", "Shell", "Java", "Unspecified"],
      values: [7, 4, 2, 2, 2, 1, 1, 1]
    }
  ];

  slide.addChart(pres.charts.DOUGHNUT, chartData, {
    x: 0.3, y: 1.4, w: 5.2, h: 3.8,
    showTitle: false,
    showLegend: true,
    legendPos: "b",
    legendFontSize: 9,
    showPercent: true,
    showValue: false,
    chartColors: [
      theme.primary,    // Python - deepest blue
      theme.accent,     // TypeScript - bright blue
      "e9c46a",         // HTML - gold
      "f4a261",         // Rust - orange
      "e76f51",         // Swift - coral
      theme.light,      // Shell - light blue
      "264653",         // Java - dark teal
      "999999"          // Unspecified - gray
    ],
    dataLabelFontSize: 9,
    dataLabelColor: theme.primary
  });

  // Right side key insights
  const insightY = 1.5;
  const insights = [
    { pct: "35%", lang: "Python", desc: "7 repos — AI/ML ecosystem's primary language", color: theme.primary },
    { pct: "20%", lang: "TypeScript", desc: "4 repos — agent UIs & developer experience", color: theme.accent },
    { pct: "10%", lang: "HTML", desc: "2 repos — design systems & docs", color: "e9c46a" },
    { pct: "10%", lang: "Rust", desc: "2 repos — performance-critical tools", color: "f4a261" },
    { pct: "10%", lang: "Swift", desc: "2 repos — macOS/iOS utilities", color: "e76f51" }
  ];

  insights.forEach((ins, i) => {
    const iy = insightY + i * 0.7;

    // Color dot
    slide.addShape(pres.shapes.OVAL, {
      x: 5.8, y: iy + 0.08, w: 0.22, h: 0.22,
      fill: { color: ins.color }
    });

    // Percentage + Language
    slide.addText([
      { text: ins.pct + "  ", options: { bold: true, fontSize: 16, fontFace: "Trebuchet MS", color: theme.primary } },
      { text: ins.lang, options: { bold: true, fontSize: 14, fontFace: "Trebuchet MS", color: theme.secondary } }
    ], {
      x: 6.15, y: iy, w: 3.5, h: 0.35,
      align: "left", valign: "middle"
    });

    // Description
    slide.addText(ins.desc, {
      x: 6.15, y: iy + 0.35, w: 3.5, h: 0.3,
      fontSize: 11, fontFace: "Calibri",
      color: "666666", bold: false, align: "left", valign: "top"
    });
  });

  // Note at bottom
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: 5.0, w: 3.9, h: 0.4,
    fill: { color: theme.primary },
    rectRadius: 0.05
  });
  slide.addText("1 repo has unspecified language (andrej-karpathy-skills)", {
    x: 5.95, y: 5.0, w: 3.6, h: 0.4,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "middle"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "f0f9ff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

