const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 5, title: 'Category Breakdown' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("14 of 20 Trending Repos Are AI Coding\nAgent or Claude Code Projects", {
    x: 0.5, y: 0.25, w: 9, h: 0.9,
    fontSize: 28, fontFace: "Trebuchet MS",
    color: theme.primary, bold: true, align: "left", valign: "middle"
  });

  // Accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.2, w: 2.0, h: 0.04,
    fill: { color: theme.accent }
  });

  // Stacked bar chart - single horizontal bar showing category proportions
  const categories = [
    { name: "AI Coding Agents\n& Skills", count: 10, pct: "50%", color: theme.primary },
    { name: "Claude Code\nEcosystem Tools", count: 5, pct: "25%", color: theme.accent },
    { name: "AI Infrastructure\n& Research", count: 3, pct: "15%", color: "e9c46a" },
    { name: "Developer\nUtilities", count: 3, pct: "15%", color: "e76f51" }
  ];

  // Build horizontal stacked bar manually with shapes
  const barY = 1.5;
  const barH = 1.4;
  const barX = 0.5;
  const totalW = 9.0;
  const total = 20; // total repos (note: some repos cross-listed)

  // Scaled proportions for visual: AI Agents 10, Claude Code 5, AI Infra 3, Dev Utils 3 = 21 (with overlap)
  // Use 14 AI-related + 3 infra + 3 utils = 20 to show 70% AI concentration
  // Break down: AI Coding Agents & Skills: 10, Claude Code Ecosystem: 5 (overlapping), AI Infra: 3, Dev Utils: 3
  // For the stacked bar, show proportional: 10+5+3+3=21 (but we note overlap)
  // Better: show as 10/5/3/3 = total 21 units
  const vals = [10, 5, 3, 3];
  const sum = 21;
  let cx = barX;

  categories.forEach((cat, i) => {
    const segW = (vals[i] / sum) * totalW;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: barY, w: segW, h: barH,
      fill: { color: cat.color }
    });

    // Label inside bar segment
    slide.addText(cat.count + " repos\n" + cat.pct, {
      x: cx, y: barY, w: segW, h: barH,
      fontSize: 13, fontFace: "Trebuchet MS",
      color: "FFFFFF", bold: true, align: "center", valign: "middle"
    });

    cx += segW;
  });

  // Category detail cards below
  const cardY = 3.2;
  const cardH = 1.6;
  const cardW = 2.15;
  const gap = 0.15;

  const catDetails = [
    {
      title: "AI Coding Agents & Skills",
      count: 10,
      repos: "hermes-agent, graphify,\ncaveman, agent-skills,\nandrej-karpathy-skills...",
      color: theme.primary
    },
    {
      title: "Claude Code Ecosystem",
      count: 5,
      repos: "claude-code-best-practice,\nclaude-howto, cc-switch,\ncaveman, learn-claude-code",
      color: theme.accent
    },
    {
      title: "AI Infrastructure & Research",
      count: 3,
      repos: "VoxCPM, reverse-SynthID,\nopendataloader-pdf",
      color: "e9c46a"
    },
    {
      title: "Developer Utilities",
      count: 3,
      repos: "InstantSpaceSwitcher,\nRecordly, rtk, clicky",
      color: "e76f51"
    }
  ];

  catDetails.forEach((cat, i) => {
    const cardX = 0.5 + i * (cardW + gap);

    slide.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: cardY, w: cardW, h: cardH,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.06 },
      rectRadius: 0.06
    });

    // Top accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: cardY, w: cardW, h: 0.06,
      fill: { color: cat.color }
    });

    // Title
    slide.addText(cat.title, {
      x: cardX + 0.1, y: cardY + 0.15, w: cardW - 0.2, h: 0.35,
      fontSize: 11, fontFace: "Trebuchet MS",
      color: cat.color, bold: true, align: "left", valign: "top"
    });

    // Repo list
    slide.addText(cat.repos, {
      x: cardX + 0.1, y: cardY + 0.55, w: cardW - 0.2, h: 0.9,
      fontSize: 9, fontFace: "Calibri",
      color: "666666", bold: false, align: "left", valign: "top"
    });
  });

  // 70% callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.0, w: 9.0, h: 0.45,
    fill: { color: theme.primary },
    rectRadius: 0.05
  });
  slide.addText("70% of trending repos directly relate to AI coding assistance — an unprecedented concentration in a single theme", {
    x: 0.7, y: 5.0, w: 8.6, h: 0.45,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "middle"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "f0f9ff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

