const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 7, title: 'Community Engagement' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("hermes-agent Draws 78 PRs and 42 Pushes", {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 28, fontFace: "Trebuchet MS",
    color: theme.primary, bold: true, align: "left", valign: "middle"
  });
  slide.addText("Community Activity Varies Widely Across Top 20 Repos", {
    x: 0.5, y: 0.75, w: 9, h: 0.35,
    fontSize: 15, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", valign: "middle"
  });

  // Accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.2, w: 2.0, h: 0.04,
    fill: { color: theme.accent }
  });

  // Grouped bar chart - PRs and Pushes for selected repos
  const repos = [
    "hermes-agent",
    "multica",
    "graphify",
    "rtk",
    "oh-my-codex",
    "cc-switch",
    "opendataloader-pdf",
    "caveman",
    "reverse-SynthID",
    "Recordly",
    "DeepTutor",
    "InstantSpaceSwitcher"
  ];

  const prs = [78, 7, 5, 5, 2, 2, 1, 1, 1, 1, 0, 0];
  const pushes = [42, 35, 6, 3, 10, 2, 3, 1, 2, 1, 2, 2];

  const chartData = [
    { name: "PRs", labels: repos, values: prs },
    { name: "Pushes", labels: repos, values: pushes }
  ];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.3, y: 1.35, w: 9.4, h: 3.2,
    barDir: "col",
    barGrouping: "clustered",
    chartColors: [theme.primary, theme.accent],
    showTitle: false,
    showLegend: true,
    legendPos: "b",
    legendFontSize: 10,
    catAxisLabelFontSize: 8,
    catAxisLabelColor: theme.secondary,
    valAxisLabelFontSize: 9,
    valAxisLabelColor: theme.secondary,
    valGridLine: { color: "e0e0e0", size: 0.5 },
    catGridLine: { style: "none" }
  });

  // Insight callout - left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.7, w: 4.3, h: 0.75,
    fill: { color: theme.primary },
    rectRadius: 0.06
  });
  slide.addText([
    { text: "High Engagement: ", options: { bold: true } },
    { text: "hermes-agent (78 PRs, 42 pushes) and multica (7 PRs, 35 pushes) show active community collaboration" }
  ], {
    x: 0.65, y: 4.7, w: 4.0, h: 0.75,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "middle"
  });

  // Insight callout - right
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: 4.7, w: 4.5, h: 0.75,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.06 },
    rectRadius: 0.06
  });
  slide.addText([
    { text: "8 of 20 repos have zero PRs ", options: { bold: true, color: theme.primary } },
    { text: "— suggesting early-stage virality rather than mature community development", options: { color: "666666" } }
  ], {
    x: 5.25, y: 4.7, w: 4.2, h: 0.75,
    fontSize: 10, fontFace: "Calibri",
    color: "666666", bold: false, align: "left", valign: "middle"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "f0f9ff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-07-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

